import heapq
from typing import List, Tuple, Optional, Dict

def shortest_path(edges: List[Tuple[str, str, float]], start: str, end: str) -> Tuple[Optional[float], Optional[List[str]]]:
    """
    Find the shortest path between start and end nodes in a weighted directed graph.

    Args:
        edges: List of tuples (from_node, to_node, weight)
        start: Starting node
        end: Target node

    Returns:
        A tuple (distance, path) where distance is the shortest path length and
        path is the list of nodes from start to end. Returns (0, [start]) if start == end.
        Returns (None, None) if no path exists.

    Raises:
        ValueError: If any edge has a negative weight.
    """
    # Handle same-node case
    if start == end:
        return (0, [start])

    # Build adjacency list (taking minimum weight for multiple edges between nodes)
    graph: Dict[str, Dict[str, float]] = {}
    for from_node, to_node, weight in edges:
        if from_node not in graph:
            graph[from_node] = {}
        existing_weight = graph[from_node].get(to_node)
        if existing_weight is None:
            graph[from_node][to_node] = weight
        else:
            graph[from_node][to_node] = min(existing_weight, weight)

    # Check for negative edge weights
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight not allowed")

    # Dijkstra's algorithm
    distance: Dict[str, float] = {start: 0}
    previous: Dict[str, str] = {}
    pq = [(0, start)]

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_dist > distance.get(current_node, float('inf')):
            continue

        if current_node == end:
            break

        if current_node not in graph:
            continue

        for neighbor, weight in graph[current_node].items():
            new_dist = current_dist + weight

            if neighbor not in distance or new_dist < distance[neighbor]:
                distance[neighbor] = new_dist
                previous[neighbor] = current_node
                heapq.heappush(pq, (new_dist, neighbor))

    # Check if end node is reachable
    if end not in distance:
        return (None, None)

    # Reconstruct path
    path: List[str] = []
    current = end
    while current != start and current is not None:
        path.append(current)
        current = previous.get(current)
    path.append(start)
    path.reverse()

    return (distance[end], path)


# Example usage:
if __name__ == "__main__":
    edges = [("A", "B", 1), ("B", "C", 2), ("A", "C", 5)]
    print(shortest_path(edges, "A", "C"))  # Output: (3, ['A', 'B', 'C'])

    edges_with_negative = [("A", "B", 1), ("B", "C", -2)]
    try:
        shortest_path(edges_with_negative, "A", "C")
    except ValueError as e:
        print(f"Error: {e}")

    no_path_edges = [("A", "B", 1), ("C", "D", 2)]
    print(shortest_path(no_path_edges, "A", "D"))  # Output: (None, None)
